"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[30717],{3331:(i,e,a)=>{a.d(e,{R:()=>r,x:()=>l});var o=a(36672);const n={},t=o.createContext(n);function r(i){const e=o.useContext(t);return o.useMemo((function(){return"function"==typeof i?i(e):{...e,...i}}),[e,i])}function l(i){let e;return e=i.disableParentContext?"function"==typeof i.components?i.components(n):i.components||n:r(i.components),o.createElement(t.Provider,{value:e},i.children)}},90187:(i,e,a)=>{a.r(e),a.d(e,{assets:()=>s,contentTitle:()=>l,default:()=>p,frontMatter:()=>r,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"2023/03/31","title":"2023-03-31","description":"La proposta di legge statunitense sul divieto solleva preoccupazioni per VPN e TikTok","source":"@site/i18n/it/docusaurus-plugin-content-docs/current/2023/03/31.md","sourceDirName":"2023/03","slug":"/2023/03/31","permalink":"/it/2023/03/31","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/it/docusaurus-plugin-content-docs//current/2023/03/31.md","tags":[],"version":"current","frontMatter":{"localized_date":"31 marzo 2023","top_news":"La proposta di legge statunitense sul divieto solleva preoccupazioni per VPN e TikTok"},"sidebar":"defaultSidebar","previous":{"title":"01","permalink":"/it/2023/04/01"},"next":{"title":"2023-03-30","permalink":"/it/2023/03/30"}}');var n=a(23420),t=a(3331);const r={localized_date:"31 marzo 2023",top_news:"La proposta di legge statunitense sul divieto solleva preoccupazioni per VPN e TikTok"},l="2023-03-31",s={},c=[{value:"La proposta di legge statunitense sul divieto solleva preoccupazioni per VPN e TikTok",id:"la-proposta-di-legge-statunitense-sul-divieto-solleva-preoccupazioni-per-vpn-e-tiktok",level:2},{value:"Opinioni contrastanti sul valore di Y Combinator per le startup",id:"opinioni-contrastanti-sul-valore-di-y-combinator-per-le-startup",level:2},{value:"Scratch: Un popolare linguaggio di programmazione visuale per bambini",id:"scratch-un-popolare-linguaggio-di-programmazione-visuale-per-bambini",level:2},{value:"Sfide e compromessi nella tecnologia di illuminazione a LED",id:"sfide-e-compromessi-nella-tecnologia-di-illuminazione-a-led",level:2},{value:"Oltre la met\xe0 dei nuovi pacchetti NPM sono spam",id:"oltre-la-met\xe0-dei-nuovi-pacchetti-npm-sono-spam",level:2},{value:"Gli Stati Uniti propongono leggi che minacciano la libert\xe0 tecnologica e la privacy",id:"gli-stati-uniti-propongono-leggi-che-minacciano-la-libert\xe0-tecnologica-e-la-privacy",level:2},{value:"Motore di rendering 3D open source per l&#39;istruzione e l&#39;integrazione",id:"motore-di-rendering-3d-open-source-per-listruzione-e-lintegrazione",level:2},{value:"Google nega di aver usato ChatGPT di OpenAI per addestrare Bard",id:"google-nega-di-aver-usato-chatgpt-di-openai-per-addestrare-bard",level:2},{value:"API di Twitter trascurate, cresce l&#39;insoddisfazione degli utenti",id:"api-di-twitter-trascurate-cresce-linsoddisfazione-degli-utenti",level:2},{value:"Il direttore del sindacato di polizia di San Jose accusato di contrabbando di droga",id:"il-direttore-del-sindacato-di-polizia-di-san-jose-accusato-di-contrabbando-di-droga",level:2}];function d(i){const e={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,t.R)(),...i.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(e.header,{children:(0,n.jsx)(e.h1,{id:"2023-03-31",children:"2023-03-31"})}),"\n",(0,n.jsx)(e.h2,{id:"la-proposta-di-legge-statunitense-sul-divieto-solleva-preoccupazioni-per-vpn-e-tiktok",children:"La proposta di legge statunitense sul divieto solleva preoccupazioni per VPN e TikTok"}),"\n",(0,n.jsxs)(e.p,{children:["Una proposta di legge statunitense sostenuta dalla Casa Bianca e finalizzata alla regolamentazione di Internet potrebbe rendere illegali le VPN, concedere multe fino a 1 milione di dollari e 20 anni di reclusione ed essere vista come un attacco alle libert\xe0 civili. Il disegno di legge gode di un sostegno bipartisan e si concentra sui problemi di sicurezza nazionale legati alla Cina e sulla limitazione dei rapporti commerciali con il Paese. L'UE potrebbe non seguire la tendenza degli Stati Uniti, in quanto i Paesi hanno una propria struttura giuridica, e il divieto di TikTok potrebbe provocare risentimento tra i giovani e ritorsioni contro il governo statunitense. I critici del divieto sostengono che esso minaccia la privacy individuale e la libert\xe0 di parola e di espressione.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35366955",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://www.youtube.com/watch?v=FWQGA_n5Z4M",children:"Post originale"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"opinioni-contrastanti-sul-valore-di-y-combinator-per-le-startup",children:"Opinioni contrastanti sul valore di Y Combinator per le startup"}),"\n",(0,n.jsxs)(e.p,{children:["Le opinioni sul valore di Y Combinator (YC) per le startup sono contrastanti, a seconda delle prospettive e delle esigenze individuali. Mentre alcuni apprezzano la rete e la mentorship di YC, altri ne criticano i consigli e l'attenzione agli obiettivi a breve termine. La reputazione e il marchio di YC possono aiutare a raccogliere fondi, ma l'accordo SAFE senza limiti e l'enfasi sulla scalabilit\xe0 a tutti i costi potrebbero non essere adatti a tutti i fondatori. Si discute anche sull'importanza della creazione di una comunit\xe0 e delle connessioni personali in un formato esclusivamente remoto. In definitiva, il valore di YC dipende dalla capacit\xe0 del fondatore di utilizzare le sue risorse per massimizzare le possibilit\xe0 di successo.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35373019",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://acecreamu.substack.com/p/is-y-combinator-worth-the-money",children:"Post originale"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"scratch-un-popolare-linguaggio-di-programmazione-visuale-per-bambini",children:"Scratch: Un popolare linguaggio di programmazione visuale per bambini"}),"\n",(0,n.jsxs)(e.p,{children:["Scratch \xe8 un popolare linguaggio di programmazione visuale rivolto ai bambini, che utilizza blocchi colorati al posto della codifica testuale per aiutarli ad apprendere i concetti di programmazione. Il programma include i principi di base della programmazione, come le variabili, gli elenchi, le strutture di flusso di controllo if/else e looping e la concomitanza di eventi. Scratch ha un approccio semplice e facile da usare per incoraggiare i bambini a esplorare il calcolo in modo creativo, oltre a una grande attenzione all'interazione tra pari e alla condivisione del lavoro per ricevere feedback. La comunit\xe0 di Scratch \xe8 una delle pi\xf9 grandi comunit\xe0 di coding al mondo, con oltre 103 milioni di utenti e 123 milioni di progetti condivisi sulla piattaforma. Anche se ci sono preoccupazioni riguardo ai social network non regolamentati e ai bambini che giocano ai videogiochi invece di usare Scratch per scopi educativi, lo strumento ha ispirato molti ad interessarsi alla programmazione, con progetti che vanno dal coding per principianti alle competenze di programmazione avanzate.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35373052",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://scratch.mit.edu/about",children:"Post originale"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"sfide-e-compromessi-nella-tecnologia-di-illuminazione-a-led",children:"Sfide e compromessi nella tecnologia di illuminazione a LED"}),"\n",(0,n.jsxs)(e.p,{children:["Le lampadine a LED presentano problemi di guasto rapido, scarsa resa cromatica e indici di somiglianza spettrale, alimentatori mal progettati, surriscaldamento e costi pi\xf9 elevati per l'illuminazione di interni. Per l'illuminazione a LED sono necessari alimentatori a corrente costante e gli apparecchi devono essere progettati in modo diverso rispetto alle lampadine a incandescenza per dissipare il calore. Ci sono dubbi sull'affidabilit\xe0 e la durata delle lampadine a LED, anche se sono disponibili opzioni di alta qualit\xe0 a un prezzo pi\xf9 elevato. L'integrazione delle lampadine a LED con gli interruttori dimmer e la garanzia di compatibilit\xe0 rappresentano una sfida. Lo sfarfallio e la mancanza di vivacit\xe0 dell'illuminazione a LED hanno portato allo sviluppo di nuovi sistemi di classificazione e di lampadine a LED sintonizzabili. Nel complesso, la tecnologia LED ha un potenziale, ma richiede uno sviluppo e un'innovazione continui.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35371750",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://nymag.com/strategist/article/led-light-bulbs-investigation.html",children:"Post originale"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"oltre-la-met\xe0-dei-nuovi-pacchetti-npm-sono-spam",children:"Oltre la met\xe0 dei nuovi pacchetti NPM sono spam"}),"\n",(0,n.jsxs)(e.p,{children:["Oltre la met\xe0 dei nuovi pacchetti npm inviati sono spam, molti dei quali contengono link a siti web dannosi o offrono falsi omaggi come i V-Bucks di Fortnite. Si pensa che l'aumento dello spam sia legato ai campi di addestramento al coding, dove gli studenti sono incoraggiati a pubblicare pacchetti anche se non fanno nulla. Gli intervistati hanno suggerito soluzioni come processi di test automatizzati e un modello di web-of-trust. Il problema mette in luce la complessa natura dell'etica nell'industria dello sviluppo del software e le tensioni tra libert\xe0 di parola e diritti di propriet\xe0 privata. I ricercatori di sicurezza hanno identificato la presenza di pacchetti spam nell'intero registro npm e stanno svolgendo ulteriori indagini.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35370728",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://blog.sandworm.dev/one-in-two-new-npm-packages-is-seo-spam-right-now",children:"Post originale"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"gli-stati-uniti-propongono-leggi-che-minacciano-la-libert\xe0-tecnologica-e-la-privacy",children:"Gli Stati Uniti propongono leggi che minacciano la libert\xe0 tecnologica e la privacy"}),"\n",(0,n.jsxs)(e.p,{children:["Il governo degli Stati Uniti ha proposto un disegno di legge che darebbe un potere senza precedenti di vietare qualsiasi tecnologia straniera ritenuta una \"minaccia alla sicurezza nazionale\", lasciando intendere che potrebbe portare a poteri di censura simili a quelli della Cina ed essere molto pi\xf9 ampio di quanto si pensasse inizialmente. Si discute anche sul divieto delle app dei social media di propriet\xe0 cinese: alcuni sostengono che si tratti di una china scivolosa verso la censura delle informazioni, mentre altri sostengono che sia necessario impedire alle aziende cinesi di rubare la tecnologia statunitense e di raccogliere informazioni a scopo di spionaggio. Il RESTRICT Act \xe8 una proposta di legge che potrebbe essere utilizzata per vietare TikTok e le VPN, e i critici sostengono che potrebbe violare il Primo Emendamento. I senatori repubblicani hanno anche proposto di vietare ai dipendenti federali l'uso di applicazioni di social media di propriet\xe0 di aziende cinesi, a causa delle preoccupazioni legate allo spionaggio e alla sorveglianza. Alcuni commentatori suggeriscono che la legislazione equivale al protezionismo del governo, mentre altri sostengono che la crescita dei social media stia danneggiando la salute mentale e contribuendo alla manipolazione dell'opinione pubblica.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35369075",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://www.vice.com/en/article/4a3ddb/restrict-act-insanely-broad-ban-tiktok-vpns",children:"Post originale"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"motore-di-rendering-3d-open-source-per-listruzione-e-lintegrazione",children:"Motore di rendering 3D open source per l'istruzione e l'integrazione"}),"\n",(0,n.jsxs)(e.p,{children:["Uno sviluppatore ha rilasciato un motore di rendering 3D open-source, StratusGFX, che pu\xf2 essere integrato in altri motori o utilizzato come risorsa didattica. Le sue funzionalit\xe0 includono riflessioni in tempo reale, ombre e supporto completo per l'ombreggiatura PBR, ma attualmente supporta solo OpenGL. Il suo creatore sta valutando la possibilit\xe0 di portare il renderer su Vulkan per migliorare la compatibilit\xe0 multipiattaforma. Il motore StratusGFX \xe8 progettato per massimizzare il realismo, ma con capacit\xe0 di compromesso di ripiego per l'hardware meno potente, e la sua architettura \xe8 disponibile su Github per Windows e Linux. Il motore \xe8 in fase di pre-release/beta-release e ci si deve aspettare bug e instabilit\xe0 significativi.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35370284",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://github.com/KTStephano/StratusGFX",children:"Post originale"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"google-nega-di-aver-usato-chatgpt-di-openai-per-addestrare-bard",children:"Google nega di aver usato ChatGPT di OpenAI per addestrare Bard"}),"\n",(0,n.jsxs)(e.p,{children:["Google nega di aver usato ChatGPT di OpenAI per addestrare Bard, un nuovo modello linguistico. Sono state sollevate preoccupazioni sull'etica dell'addestramento di un modello linguistico di grandi dimensioni con i risultati di un altro LLM controllato commercialmente. I termini di servizio di OpenAI vietano l'addestramento di modelli concorrenti attraverso i suoi risultati di ML, ma Google non \xe8 vincolata da questo. Un ex dipendente di Google ha affermato di aver utilizzato i dati di OpenAI, ma Google lo nega. Il materiale generato dall'intelligenza artificiale non \xe8 protetto da copyright e l'addestramento su altri modelli \xe8 consentito. Alcuni sostengono che rubare da ChatGPT potrebbe essere moralmente giustificato, dal momento che si tratta di una fonte di gruppo, ma che l'addestramento dei modelli su altri dati generati dall'IA potrebbe creare dati sbagliati.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35370915",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://twitter.com/steventey/status/1641267979399704576",children:"Post originale"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"api-di-twitter-trascurate-cresce-linsoddisfazione-degli-utenti",children:"API di Twitter trascurate, cresce l'insoddisfazione degli utenti"}),"\n",(0,n.jsxs)(e.p,{children:["Secondo quanto riferito, l'API di Twitter non viene mantenuta, con conseguenti problemi di instabilit\xe0 per gli utenti. Alcuni utenti hanno riferito di sentirsi estranei al servizio a causa della diminuzione dei contenuti scientifici e dell'aumento dei contenuti infiammatori o offensivi. Molte piattaforme di social media utilizzano feed algoritmici, ma le impostazioni predefinite sono importanti perch\xe9 influenzano il comportamento degli utenti. Gli utenti di Twitter stanno riscontrando problemi come errori interni del server e difficolt\xe0 di accesso al sito web, che hanno portato alcuni a passare a piattaforme alternative come Mastodon. I recenti problemi di instabilit\xe0 di Twitter hanno indotto alcuni utenti a ridurre il loro utilizzo. Nonostante queste preoccupazioni, alcuni ritengono che la crescita di Twitter sotto la guida di Musk suggerisca che la piattaforma continuer\xe0 a prosperare, con o senza i suoi affezionati utenti. La decisione di Elon Musk di limitare l'accesso alle API di Twitter sta suscitando polemiche, con i critici che lo accusano di aver intenzionalmente portato Twitter al collasso. L'API di Twitter \xe8 ora di fatto priva di manutenzione, con un solo dipendente che pubblica regolarmente sul forum Twitter Developers e si concentra esclusivamente sull'API Ads.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35370152",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://snarfed.org/the-twitter-api-is-now-effectively-unmaintained",children:"Post originale"}),"."]}),"\n",(0,n.jsx)(e.h2,{id:"il-direttore-del-sindacato-di-polizia-di-san-jose-accusato-di-contrabbando-di-droga",children:"Il direttore del sindacato di polizia di San Jose accusato di contrabbando di droga"}),"\n",(0,n.jsxs)(e.p,{children:["Il direttore esecutivo dell'Associazione dei funzionari di polizia di San Jose, Sonia Rosa Segovia, \xe8 stata accusata di contrabbando di fentanil negli Stati Uniti e di aver gestito un'attivit\xe0 di spaccio in parte dall'ufficio. La Segovia avrebbe usato l'indirizzo dell'associazione per inviare pacchi ai clienti e avrebbe discusso di affari di polizia con i suoi fornitori. Almeno uno dei suoi clienti \xe8 morto per overdose e lei deve rispondere di molteplici accuse legate alla droga. Altri casi di agenti di polizia coinvolti nel traffico di droga hanno sollevato interrogativi sul ruolo delle forze dell'ordine nel traffico illegale di droga, e alcuni suggeriscono la legalizzazione come soluzione. La conversazione sulla legalizzazione delle droghe tocca anche le esternalit\xe0 e la necessit\xe0 di sistemi di supporto. Anche la direttrice esecutiva del sindacato di polizia di San Jose, Joanne Southerland, \xe8 stata accusata di contrabbando di droga, cos\xec come Joanne Segovia, dipendente del sindacato di polizia, \xe8 stata incriminata con l'accusa di aver importato metanfetamina negli Stati Uniti. Questi casi evidenziano la necessit\xe0 di soluzioni per affrontare il traffico di droga e la dipendenza, compresi i cambiamenti culturali e gli sforzi mirati delle forze dell'ordine.\n",(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35376488",children:"Hacker News Link"}),", ",(0,n.jsx)(e.a,{href:"https://www.washingtonexaminer.com/news/crime/san-jose-police-union-director-smuggle-fentanyl-charge",children:"Post originale"}),"."]})]})}function p(i={}){const{wrapper:e}={...(0,t.R)(),...i.components};return e?(0,n.jsx)(e,{...i,children:(0,n.jsx)(d,{...i})}):d(i)}}}]);